<?php foreach ($integrations as $i => [$name, $on, $note]): ?><div class="row between" style="padding:12px 0;border-top:1px solid var(--glass)"><div><b><?= ($i + 1) . ' · ' . e($name) ?></b><div class="small mute"><?= e($note) ?></div></div><span class="pill <?= $on ? 'ok' : 'warn' ?>"><?= $on ? 'Connected' : 'Not connected' ?></span></div><?php endforeach; ?></div></div>
